use std::io
use std::collections::HashMap

fn main() {
    let s = io::read_to_string() ?? ""
    let mut k: i64 = 0
    let mut rest = ""
    let mut first = true
    for line in s.lines() {
        if first {
            k = line.trim().parse::<i64>() ?? 0
            first = false
        } else {
            rest = rest + line + "\n"
        }
    }
    let mut counts: HashMap<string, i64> = HashMap::new()
    let mut cur = ""
    for c in rest.chars() {
        if c.is_ascii_alphanumeric() {
            cur = cur + c.to_ascii_lowercase().to_string()
        } else if cur.len() > 0 {
            *counts.entry(cur).or_insert(0) += 1
            cur = ""
        }
    }
    if cur.len() > 0 {
        *counts.entry(cur).or_insert(0) += 1
    }
    let mut items: Vec<(string, i64)> = Vec::new()
    for (w, n) in counts {
        items.push((w, n))
    }
    items.sort_by(|a, b| {
        if a.1 != b.1 {
            b.1.cmp(a.1)
        } else {
            a.0.cmp(b.0)
        }
    })
    let mut i: i64 = 0
    for it in items {
        if i >= k {
            break
        }
        println("${it.0} ${it.1}")
        i += 1
    }
}

